CREATE TABLE users (id BIGSERIAL PRIMARY KEY,email TEXT NOT NULL UNIQUE,name TEXT NOT NULL,password_hash TEXT NOT NULL DEFAULT '',role TEXT NOT NULL DEFAULT 'reader' CHECK(role IN ('reader','admin')),verified BOOLEAN NOT NULL DEFAULT false,suspended BOOLEAN NOT NULL DEFAULT false,bio TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE identities (provider TEXT NOT NULL,subject TEXT NOT NULL,user_id BIGINT NOT NULL REFERENCES users ON DELETE CASCADE,PRIMARY KEY(provider,subject),UNIQUE(provider,user_id));
CREATE TABLE sessions (hash TEXT PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users ON DELETE CASCADE,csrf TEXT NOT NULL,expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE account_tokens (hash TEXT PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users ON DELETE CASCADE,purpose TEXT NOT NULL,expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE oauth_states (hash TEXT PRIMARY KEY,nonce TEXT NOT NULL,verifier TEXT NOT NULL,link_user BIGINT REFERENCES users ON DELETE CASCADE,expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE authors (id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL UNIQUE,bio TEXT NOT NULL DEFAULT '',avatar TEXT NOT NULL DEFAULT '');
INSERT INTO authors(name) SELECT DISTINCT author FROM posts WHERE author<>'' ON CONFLICT DO NOTHING;
CREATE TABLE topics (name TEXT PRIMARY KEY,description TEXT NOT NULL DEFAULT '');
INSERT INTO topics(name) SELECT DISTINCT category FROM posts ON CONFLICT DO NOTHING;
ALTER TABLE posts ADD COLUMN content JSONB;
ALTER TABLE posts ADD COLUMN scheduled_at TIMESTAMPTZ;
CREATE TABLE post_revisions (id BIGSERIAL PRIMARY KEY,slug TEXT NOT NULL REFERENCES posts ON DELETE CASCADE,snapshot JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE comments (id BIGSERIAL PRIMARY KEY,slug TEXT NOT NULL REFERENCES posts ON DELETE CASCADE,user_id BIGINT NOT NULL REFERENCES users,parent_id BIGINT REFERENCES comments,body TEXT NOT NULL,hidden BOOLEAN NOT NULL DEFAULT false,deleted BOOLEAN NOT NULL DEFAULT false,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX comments_article ON comments(slug,created_at);
CREATE TABLE reports (id BIGSERIAL PRIMARY KEY,comment_id BIGINT NOT NULL REFERENCES comments ON DELETE CASCADE,user_id BIGINT NOT NULL REFERENCES users,reason TEXT NOT NULL,resolved BOOLEAN NOT NULL DEFAULT false,UNIQUE(comment_id,user_id));
CREATE TABLE likes (user_id BIGINT REFERENCES users ON DELETE CASCADE,slug TEXT REFERENCES posts ON DELETE CASCADE,PRIMARY KEY(user_id,slug));
CREATE TABLE bookmarks (user_id BIGINT REFERENCES users ON DELETE CASCADE,slug TEXT REFERENCES posts ON DELETE CASCADE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(user_id,slug));
CREATE TABLE follows (user_id BIGINT REFERENCES users ON DELETE CASCADE,kind TEXT CHECK(kind IN ('author','topic')),target TEXT NOT NULL,PRIMARY KEY(user_id,kind,target));
CREATE TABLE notifications (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users ON DELETE CASCADE,title TEXT NOT NULL,url TEXT NOT NULL,seen BOOLEAN NOT NULL DEFAULT false,event_key TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(user_id,event_key));
CREATE TABLE subscriptions (user_id BIGINT PRIMARY KEY REFERENCES users ON DELETE CASCADE,frequency TEXT NOT NULL DEFAULT 'off' CHECK(frequency IN ('off','immediate','weekly')),scope TEXT NOT NULL DEFAULT 'all' CHECK(scope IN ('all','following')),unsubscribe_hash TEXT NOT NULL UNIQUE);
CREATE TABLE publications (slug TEXT PRIMARY KEY REFERENCES posts ON DELETE CASCADE,first_at TIMESTAMPTZ NOT NULL DEFAULT now());
INSERT INTO publications(slug,first_at) SELECT slug,COALESCE(published_at,created_at) FROM posts WHERE status='published';
CREATE TABLE email_outbox (id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users ON DELETE CASCADE,recipient TEXT NOT NULL,subject TEXT NOT NULL,html TEXT NOT NULL,event_key TEXT NOT NULL UNIQUE,kind TEXT NOT NULL DEFAULT 'account',state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','sending','sent','failed','cancelled')),attempts INT NOT NULL DEFAULT 0,available_at TIMESTAMPTZ NOT NULL DEFAULT now(),locked_at TIMESTAMPTZ,last_error TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),sent_at TIMESTAMPTZ);
CREATE INDEX email_outbox_pending ON email_outbox(state,available_at);
CREATE TABLE digest_runs (week TEXT PRIMARY KEY);
CREATE TABLE media (id TEXT PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users,filename TEXT NOT NULL,width INT NOT NULL,height INT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE rate_limits (key TEXT PRIMARY KEY,count INT NOT NULL,expires_at TIMESTAMPTZ NOT NULL);
